if (PlacementDecoItemDefinition == nullptr) { return false; }
AActor* Candidate = FirstItemOf(PlacementDecoItemDefinition);   // FUN_142672c10 -> FUN_142659660 on +0x740 (PARTIAL)
if (Candidate == nullptr || !Candidate->IsA(AFortWeapon::StaticClass())) { return false; }   // FUN_142b43730
AFortWeapon* Equipped = EquipWeaponDefinitionImpl(PlacementDecoItemDefinition, kInvalidItemEntryGuid);   // FUN_1423150b0, constant guid at 0x1478de6a0
if (Equipped != nullptr && Equipped->IsA(AFortDecoTool::StaticClass())) {   // FUN_1428d44f0
    Equipped->SetPlacementDecoItemDefinition(PlacementDecoItemDefinition, true);   // slot 0xae8 (unnamed)
    Equipped->SetPickupTarget(PickupTarget);                                   // slot 0xaf0 (unnamed)
    return true;
}
